use leptos::prelude::*;
use serde::{Deserialize,Serialize};
use gloo_storage::{LocalStorage,Storage};
#[derive(Clone,Serialize,Deserialize)] struct Product{name:String,price:i64,icon:String}
#[derive(Clone,Serialize,Deserialize)] struct Line{name:String,qty:u32,price:i64}
impl Line{fn total(&self)->i64{self.price*self.qty as i64}}
#[derive(Clone,Serialize,Deserialize)] struct Tx{customer:String,date:String,status:String,total:i64,items:Vec<Line>}
fn rp(n:i64)->String{format!("Rp {}",n.to_string().as_bytes().rchunks(3).rev().map(|x|std::str::from_utf8(x).unwrap_or("")).collect::<Vec<_>>().join("."))}
fn main(){mount_to_body(App)}
#[component] fn App()->impl IntoView{
 let defaults=vec![
 Product{name:"Aqua".into(),price:5000,icon:"💧".into()},Product{name:"Indomie".into(),price:3000,icon:"🍜".into()},Product{name:"Telur".into(),price:2000,icon:"🥚".into()},Product{name:"Kopi".into(),price:4000,icon:"☕".into()},Product{name:"Es Teh".into(),price:3000,icon:"🧋".into()},Product{name:"Gas 3kg".into(),price:18000,icon:"🛢️".into()},Product{name:"Rokok".into(),price:18000,icon:"📦".into()},Product{name:"Mie Goreng".into(),price:3000,icon:"🍝".into()}];
 let (products,set_products)=signal(LocalStorage::get("wk_rust_products").unwrap_or(defaults));
 let (history,set_history)=signal(LocalStorage::get::<Vec<Tx>>("wk_rust_history").unwrap_or_default());
 let (cart,set_cart)=signal(Vec::<Line>::new());let (page,set_page)=signal("Kasir".to_string());
 let (customer,set_customer)=signal(String::new());let (status,set_status)=signal("Lunas".to_string());
 let (url,set_url)=signal(LocalStorage::get::<String>("wk_rust_sheet_url").unwrap_or_default());
 let (toast,set_toast)=signal(String::new());let (new_name,set_new_name)=signal(String::new());let (new_price,set_new_price)=signal(String::new());
 let total=move ||cart.get().iter().map(Line::total).sum::<i64>();
 let debt=move ||history.get().iter().map(|t|if t.status=="Utang"{t.total}else if t.status=="Pelunasan"{-t.total}else{0}).sum::<i64>().max(0);
 let sales=move ||history.get().iter().filter(|t|t.status!="Utang").map(|t|t.total).sum::<i64>();
 let add=move |p:Product|set_cart.update(|c|if let Some(x)=c.iter_mut().find(|x|x.name==p.name){x.qty+=1}else{c.push(Line{name:p.name,qty:1,price:p.price})});
 let save=move |_|{let n=customer.get().trim().to_string();if n.is_empty(){set_toast.set("Isi nama pelanggan dulu.".into());return}if cart.get().is_empty(){set_toast.set("Keranjang masih kosong.".into());return}
 let tx=Tx{customer:n,date:js_sys::Date::new_0().to_iso_string().as_string().unwrap_or_default(),status:status.get(),total:total(),items:cart.get()};
 set_history.update(|h|h.insert(0,tx));let _=LocalStorage::set("wk_rust_history",history.get());set_cart.set(vec![]);set_customer.set(String::new());set_toast.set("Transaksi tersimpan di perangkat ini.".into());};
 let nav=[("Kasir","▣"),("Utang","◷"),("Riwayat","↺"),("Laporan","▤"),("Produk","◇"),("Pengaturan","⚙")];
 view!{<div class="shell"><aside><div class="brand">"◈ WARUNGKU"</div><nav>{nav.into_iter().map(|(n,ic)|view!{<button class="nav" class:active=move || page.get()==n on:click=move |_|set_page.set(n.into())>{format!("{}  {}",ic,n)}</button>}).collect_view()}</nav></aside>
 <main><div class="top"><div><div class="eyebrow">"MANAGEMENT • WARUNG"</div><h1>{move ||page.get()}</h1><div class="muted">"Kelola transaksi dan catatan warung dengan lebih mudah."</div></div><div class="pill">"● SISTEM AKTIF"</div></div>
 <Show when=move || { page.get()=="Kasir" }><div class="stats"><div class="stat"><small>"Jumlah transaksi"</small><strong>{move ||history.get().len()}</strong></div><div class="stat"><small>"Uang masuk"</small><strong class="green">{move ||rp(sales())}</strong></div><div class="stat"><small>"Sisa utang"</small><strong>{move ||rp(debt())}</strong></div></div><div class="grid"><section class="panel"><h2>"Pilih Produk"</h2><div class="products">{move || products.get().into_iter().map(|p| view! { <div class="product"><div><b>{format!("{} {}",p.icon,p.name)}</b><small>{rp(p.price)}</small></div><button class="smallbtn" on:click=move |_|add(p.clone())>"+ Tambah"</button></div> }).collect_view()}</div></section>
 <section class="panel"><h2>"Keranjang Transaksi"</h2><label>"Nama pelanggan"</label><input class="field" placeholder="Nama pelanggan" prop:value=move || { customer.get() } on:input=move |e|set_customer.set(event_target_value(&e))/><div class="formrow"><div><label>"Jenis transaksi"</label><select class="field" on:change=move |e|set_status.set(event_target_value(&e))><option>"Lunas"</option><option>"Utang"</option></select></div><div><label>"Tanggal"</label><input class="field" value="Otomatis" disabled/></div></div><div class="list">{move || cart.get().into_iter().map(|item| view! { <div class="rowitem"><div><b>{item.name.clone()}</b><small>{format!("{} × {}",item.qty,rp(item.price))}</small></div><div><b>{rp(item.total())}</b><button class="smallbtn" on:click=move |_|set_cart.update(|c|{if let Some(i)=c.iter().position(|x|x.name==item.name){c.remove(i);}})>"Hapus"</button></div></div> }).collect_view()}</div><div class="total"><span>"Total"</span><strong>{move ||rp(total())}</strong></div><button class="btn wide" on:click=save>"Simpan Transaksi"</button></section></div></Show>
 <Show when=move || { page.get()=="Utang" }><div class="stats"><div class="stat"><small>"Total saldo utang"</small><strong>{move ||rp(debt())}</strong></div></div><section class="panel"><h2>"Catatan utang"</h2><div class="tablewrap"><table><thead><tr><th>"Pelanggan"</th><th>"Tanggal"</th><th>"Jumlah"</th><th>"Jenis"</th></tr></thead><tbody>{move || history.get().into_iter().filter(|t|t.status=="Utang"||t.status=="Pelunasan").map(|t| view! { <tr><td>{t.customer}</td><td>{t.date.chars().take(10).collect::<String>()}</td><td>{rp(t.total)}</td><td>{t.status}</td></tr> }).collect_view()}</tbody></table></div></section></Show>
 <Show when=move || { page.get()=="Riwayat" }><section class="panel"><h2>"Riwayat Transaksi"</h2><div class="tablewrap"><table><thead><tr><th>"Tanggal"</th><th>"Pelanggan"</th><th>"Barang"</th><th>"Total"</th><th>"Status"</th></tr></thead><tbody>{move || history.get().into_iter().map(|t| view! { <tr><td>{t.date.chars().take(16).collect::<String>()}</td><td>{t.customer}</td><td>{t.items.iter().map(|x|format!("{} ({})",x.name,x.qty)).collect::<Vec<_>>().join(", ")}</td><td>{rp(t.total)}</td><td>{t.status}</td></tr> }).collect_view()}</tbody></table></div></section></Show>
 <Show when=move || { page.get()=="Laporan" }><div class="stats"><div class="stat"><small>"Uang masuk"</small><strong class="green">{move ||rp(sales())}</strong></div><div class="stat"><small>"Sisa utang"</small><strong>{move ||rp(debt())}</strong></div><div class="stat"><small>"Transaksi"</small><strong>{move ||history.get().len()}</strong></div></div><section class="panel"><h2>"Ringkasan"</h2><p class="muted">"Data laporan dihitung dari riwayat transaksi perangkat ini."</p></section></Show>
 <Show when=move || { page.get()=="Produk" }><section class="panel"><h2>"Kelola Produk"</h2><div class="formrow"><div><label>"Nama produk"</label><input class="field" prop:value=move || { new_name.get() } on:input=move |e|set_new_name.set(event_target_value(&e)) placeholder="Nama produk"/></div><div><label>"Harga"</label><input class="field" type="number" prop:value=move || { new_price.get() } on:input=move |e|set_new_price.set(event_target_value(&e)) placeholder="Harga rupiah"/></div></div><button class="btn" on:click=move |_|{let n=new_name.get().trim().to_string();let p=new_price.get().parse::<i64>().unwrap_or(-1);if n.is_empty()||p<0{set_toast.set("Lengkapi nama dan harga.".into())}else{set_products.update(|v|v.push(Product{name:n,price:p,icon:"🛍️".into()}));let _=LocalStorage::set("wk_rust_products",products.get());set_new_name.set(String::new());set_new_price.set(String::new());set_toast.set("Produk ditambahkan.".into())}}>"+ Tambah Produk"</button><div class="list" style="margin-top:16px">{move || products.get().into_iter().map(|p| view! { <div class="rowitem"><div><b>{format!("{} {}",p.icon,p.name)}</b><small>{rp(p.price)}</small></div><button class="smallbtn" on:click=move |_|{set_products.update(|v|v.retain(|x|x.name!=p.name));let _=LocalStorage::set("wk_rust_products",products.get());}>"Hapus"</button></div> }).collect_view()}</div></section></Show>
 <Show when=move || { page.get()=="Pengaturan" }><section class="panel"><h2>"Google Sheets"</h2><p class="muted">"Simpan URL Apps Script. Integrasi transaksi otomatis akan disempurnakan setelah payload diuji."</p><label>"URL Web App /exec"</label><input class="field" placeholder="https://script.google.com/macros/s/.../exec" prop:value=move || { url.get() } on:input=move |e|set_url.set(event_target_value(&e))/><button class="btn" on:click=move |_|{let _=LocalStorage::set("wk_rust_sheet_url",url.get());set_toast.set("URL disimpan di perangkat.".into())}>"Simpan URL"</button></section></Show>
 </main></div><Show when=move || { !toast.get().is_empty() }><div class="toast" on:click=move |_|set_toast.set(String::new())>{move ||toast.get()}</div></Show>}
}